<script setup>
import {ref,computed,onMounted,watch} from 'vue';
import {resourceIcon,resourceIconIsPlaceholder} from './dojo/icons.js';
import {backgroundRead} from './background-read.js';
import {groupChecklistRows} from './checklist-groups.js';
import {rewardIcons} from './bounty-icons.js';
const props=defineProps({embedded:Boolean,groups:Array,checklistRoles:Array,activeRole:String});
const emit=defineEmits(['group','select','refresh-roles']);
const roleSearch=ref(''),list=ref(null);
const folded=ref([]);
try{const saved=JSON.parse(localStorage.getItem('weekly-shop-folded')||'[]');if(Array.isArray(saved))folded.value=saved.filter(x=>typeof x==='string')}catch{}
function saveFold(){try{localStorage.setItem('weekly-shop-folded',JSON.stringify(folded.value))}catch{}}
function toggleShop(name){folded.value=folded.value.includes(name)?folded.value.filter(x=>x!==name):[...folded.value,name];saveFold()}
function foldAll(value){folded.value=value?[...new Set([...folded.value,...currentGroups.value.map(g=>g.name)])]:folded.value.filter(n=>!currentGroups.value.some(g=>g.name===n));saveFold()}
const data=ref({roles:{},visible:null}),windows=ref([]),target=ref('all'),roleKey=ref(''),shop=ref('全部商店'),search=ref(''),busy=ref(false),message=ref(''),editing=ref(false),draft=ref([]);
const roles=computed(()=>Object.values(data.value.roles||{}).map(r=>({...r,group_id:props.checklistRoles?.find(x=>x.key===r.key)?.group_id||''})));
const selectedRole=computed(()=>roles.value.find(r=>r.key===roleKey.value));
const roleGroups=computed(()=>groupChecklistRows(props.groups,roles.value.filter(r=>(r.name+' '+r.server).includes(roleSearch.value.trim()))));
watch([roles,()=>props.activeRole],()=>{if(roles.value.some(r=>r.key===props.activeRole))roleKey.value=props.activeRole;else if(!roles.value.some(r=>r.key===roleKey.value))roleKey.value=roles.value[0]?.key||''});
watch(roleKey,()=>requestAnimationFrame(()=>{if(list.value)list.value.scrollTop=0}));
function selectRole(key){roleKey.value=key;emit('select',key)}
const priority=g=>g.product===411?0:g.product===490001?1:g.product===434111||g.key==='705'?2:10;
const catalogue=computed(()=>{const map=new Map();for(const r of roles.value)for(const g of r.goods)map.set(g.key,g);return [...map.values()].sort((a,b)=>a.shop.localeCompare(b.shop,'zh-CN')||priority(a)-priority(b)||a.name.localeCompare(b.name,'zh-CN'))});
const shops=computed(()=>['全部商店',...new Set(catalogue.value.map(g=>g.shop))]);
const visibleKeys=computed(()=>{const known=new Set(catalogue.value.map(g=>g.key));return (data.value.visible??catalogue.value.filter(g=>priority(g)<10||g.key==='10').map(g=>g.key)).filter(k=>known.has(k))});
const matches=g=>(shop.value==='全部商店'||g.shop===shop.value)&&(!search.value||g.name.includes(search.value));
const candidates=computed(()=>catalogue.value.filter(matches));
const sections=computed(()=>roles.value.filter(r=>r.key===roleKey.value).map(r=>({...r,groups:shops.value.slice(1).map(name=>({name,goods:r.goods.filter(g=>g.shop===name&&visibleKeys.value.includes(g.key)&&matches(g)).sort((a,b)=>priority(a)-priority(b)||a.name.localeCompare(b.name,'zh-CN'))})).filter(g=>g.goods.length)})).filter(r=>r.groups.length));
const iconId=g=>({940000:412,440045:434111,440024:-1006}[g.product]||g.product);
const icon=(id,name='')=>{const mapped=iconId({product:id});return !resourceIconIsPlaceholder(mapped)?resourceIcon(mapped):rewardIcons[name]?.url||''};
const balances=(r,group)=>[...new Map(group.goods.flatMap(g=>g.costs).map(c=>[String(c.id),{id:c.id,name:c.name,...(r.balances?.[String(c.id)]||{})}])).values()];
const number=n=>Number(n).toLocaleString('zh-CN');
const money=id=>({900001:'金币',900016:'勋章',900090:'功勋',900507:'名士荣誉',900819:'赛年荣誉',9491001:'赛事赏金',900178:'御札',900188:'金御札',900216:'八岐大蛇鳞片',900218:'逢魔之魂',900012:'荣誉',900002:'勾玉',9701029:'鼬乐园代币',900006:'友情点'}[id]||'货币');
const stale=r=>{const day=new Date();const local=new Date(day.toLocaleString('en-US',{timeZone:'Asia/Shanghai'}));local.setDate(local.getDate()-(local.getDay()+6)%7);const week=local.getFullYear()+'-'+String(local.getMonth()+1).padStart(2,'0')+'-'+String(local.getDate()).padStart(2,'0');return r.week!==week};
async function call(action,payload={}){const r=await window.pywebview.api.weekly_shops(action,payload);if(!r.ok)throw Error(r.error);return r.data}
async function refreshWindows(){try{windows.value=await call('windows');if(target.value!=='all'&&!windows.value.some(w=>w.id===target.value))target.value='all'}catch(e){message.value=e.message}}
async function load(){try{data.value=await call('load')}catch(e){message.value=e.message}}
async function read(){if(busy.value)return;busy.value=true;try{const result=await backgroundRead('shops',{target:target.value});data.value=result.snapshot;emit('refresh-roles');message.value=result.results.map(x=>x.title+'：'+(x.error||'已读取 '+x.count+' 件商品'+(x.warning?'；'+x.warning:''))).join('；')}catch(e){message.value=e.message}finally{busy.value=false}}
function edit(){draft.value=[...visibleKeys.value];editing.value=true}
function toggle(g,checked){draft.value=checked?[...new Set([...draft.value,g.key])]:draft.value.filter(k=>k!==g.key)}
async function save(){try{data.value=await call('display',{keys:draft.value});editing.value=false}catch(e){message.value=e.message}}
onMounted(()=>{load();refreshWindows()});

const shownCount=computed(()=>sections.value.reduce((n,r)=>n+r.groups.reduce((a,g)=>a+g.goods.length,0),0));
const currentGroups=computed(()=>sections.value[0]?.groups||[]);
</script>
<template><div class="weekly-shops" :class="{'workspace-page':!embedded}">
<header class="workspace-header" :class="{'embedded-header':embedded}"><div v-if="!embedded"><h1>周商店</h1><p>查看购买数量与货币余额，选择你关心的商品</p></div><Teleport :to="embedded ? '#checklist-shop-actions' : 'body'" :disabled="!embedded"><div class="actions workspace-actions"><button :disabled="busy" @click="load">刷新记录</button><select aria-label="周商店游戏窗口" v-model="target" :disabled="busy"><option value="all">所有运行窗口</option><option v-for="w in windows" :key="w.id" :value="w.id">{{w.title}}</option></select><button :disabled="busy" @click="refreshWindows">刷新窗口</button><button class="primary" :disabled="busy" @click="read">{{busy?'正在读取…':target==='all'?'读取全部窗口':'读取所选窗口'}}</button></div></Teleport></header>

<p v-if="message" class="notice" role="status">{{message}}</p>
<div class="shop-layout"><aside class="shop-role-nav"><div class="role-nav-head"><span>角色</span><small>{{roles.length}} 位</small></div><input class="role-search" aria-label="搜索周商店角色" v-model="roleSearch" placeholder="搜索角色 / 区服"><div class="shop-role-scroll"><section v-for="g in roleGroups" :key="g.id"><button class="nav-group-toggle" :aria-expanded="!!roleSearch||!g.collapsed" @click="emit('group',{action:'toggle',id:g.id,collapsed:!g.collapsed})"><span>{{roleSearch||!g.collapsed?'▾':'▸'}} {{g.name}}</span><small>{{g.rows.length}}</small></button><div v-if="roleSearch||!g.collapsed"><button v-for="r in g.rows" :key="r.key" class="role-choice" :class="{selected:r.key===roleKey}" @click="selectRole(r.key)"><span><strong>{{r.name}}</strong><small>{{r.server}}</small></span></button></div></section><p v-if="!roleGroups.length" class="nav-empty">{{roles.length?'没有匹配的角色':'读取窗口后显示角色'}}</p></div></aside>
<section class="shop-panel"><div class="role-heading"><div><h2>{{selectedRole?.name||'周商店'}}</h2><span>{{selectedRole?.server}}</span></div><small v-if="selectedRole">{{stale(selectedRole)?'上周记录 · 请重新读取':'本周记录'}} · {{selectedRole.at?.slice(5,16).replace('T',' ')}}</small></div>
<div class="shop-list-tools"><select aria-label="周商店类别" v-model="shop"><option v-for="name in shops" :key="name">{{name}}</option></select><input aria-label="搜索周商店商品" v-model="search" placeholder="搜索商品名称"><button @click="edit" :disabled="!catalogue.length||busy">显示商品 · {{visibleKeys.length}}</button></div>
<div class="shop-summary"><span><b>{{shownCount}}</b> 件商品</span><span>{{currentGroups.length}} 家商店</span><div v-if="currentGroups.length" class="fold-tools"><button @click="foldAll(false)">全部展开</button><button @click="foldAll(true)">全部收起</button></div></div>
<div class="shop-scroll" ref="list">
<section v-if="editing" class="chooser"><div class="chooser-head"><div><h2>选择显示的商品</h2><p>选择会保存在本地，对全部角色生效。</p></div><div class="actions"><button @click="draft=catalogue.map(g=>g.key)">全选</button><button @click="draft=[]">全不选</button><button @click="editing=false">取消</button><button class="primary" @click="save">保存显示</button></div></div><div class="choices"><label v-for="g in candidates" :key="g.key"><input type="checkbox" :checked="draft.includes(g.key)" @change="toggle(g,$event.target.checked)"><span><strong>{{g.name}}</strong><small>{{g.shop}}</small></span></label></div></section>

<section v-for="group in currentGroups" :key="group.name" class="shop-group"><div class="shop-group-heading"><h3><button class="shop-fold" :aria-expanded="!folded.includes(group.name)" @click="toggleShop(group.name)"><span>{{folded.includes(group.name)?'▸':'▾'}}</span>{{group.name}}<small>{{group.goods.length}} 件</small></button></h3><div class="wallets"><span v-for="c in balances(selectedRole,group)" :key="c.id" :title="c.name||money(c.id)"><img v-if="icon(c.id,c.name)" :src="icon(c.id,c.name)" alt=""><span>{{c.name||money(c.id)}}</span><b>{{c.amount===undefined?'余额未读到':number(c.amount)}}</b></span></div></div><div v-if="!folded.includes(group.name)" class="shop-cards"><article v-for="g in group.goods" :key="g.key" class="shop-item-card" :class="{sold:g.remaining===0}" :data-product-key="g.key"><div class="card-name"><img v-if="icon(g.product,g.name)" :src="icon(g.product,g.name)" alt=""><div><strong>{{g.name}}</strong><small>每份 × {{g.quantity}}<span v-if="g.stale"> · 上次记录</span></small></div></div><div class="card-purchase"><span>已购 <b>{{g.bought}}</b> / {{g.limit}}</span><small>{{g.limit_label||(g.cycle==='period'?'本期':'每周')}}限购<span v-if="g.remaining!==undefined"> · 剩余 {{g.remaining}}</span></small></div><small v-if="g.requirements?.length" class="card-requirements">{{g.requirements.join(' · ')}}</small><div class="card-price"><span v-for="c in g.costs" :key="c.id"><img v-if="icon(c.id,c.name)" :src="icon(c.id,c.name)" alt="">{{number(c.amount)}} {{c.name||money(c.id)}}</span><span v-if="!g.costs.length">—</span><small>/ 份</small></div></article></div></section>
<div v-if="!shownCount" class="empty">{{!roles.length?'读取运行中的角色，建立周商店记录。':'当前没有显示的商品，可调整筛选或点击“显示商品”。'}}</div></div></section></div>
<footer>显示选择和角色记录保存在本地；货币与限购数据仅供查看。</footer></div></template>
<style scoped>
.weekly-shops{height:100%;box-sizing:border-box;padding:24px;background:#f6f2e9;color:#3b413b;display:flex;flex-direction:column;min-height:0;overflow:hidden}.embedded-header{display:none!important}.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}button,input,select{font:inherit;font-size:12px;color:inherit;border:1px solid #dfd3bf;border-radius:6px;background:#fffcf6;padding:8px 10px;min-width:0}button{cursor:pointer}button:disabled{opacity:.45}button.primary{background:#456052;color:#fff;border-color:#456052}h1{font-size:25px;margin:0 0 7px}p{font-size:12px;color:#998a74;margin:0;line-height:1.8}.notice{flex:none;max-height:75px;overflow:auto;padding:12px;background:#eee4cf;border-radius:7px;margin-bottom:16px}.shop-layout{display:grid;grid-template-columns:195px minmax(0,1fr);gap:24px;flex:1;min-height:0;overflow:hidden}.shop-role-nav{display:flex;flex-direction:column;min-height:0;overflow:hidden}.role-nav-head{display:flex;justify-content:space-between;padding:0 8px 12px;color:#8e806c;font-size:12px}.role-nav-head small{font-size:11px}.role-search{width:100%;margin-bottom:12px;background:transparent}.shop-role-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding-right:5px}.nav-group-toggle{display:flex;align-items:center;justify-content:space-between;width:100%;margin:7px 0 5px;padding:7px 8px;border:0;background:#ece7da;color:#897c69;font-size:11px;text-align:left}.nav-group-toggle small{font-size:10px}.role-choice{display:block;width:100%;text-align:left;border-color:transparent;background:transparent;padding:11px 10px;margin-bottom:3px}.role-choice strong{display:block;font-size:13px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.role-choice small{display:block;font-size:11px;color:#a18c70;margin-top:5px}.role-choice.selected{background:#e9e1d1;border-color:#e1d3bc;box-shadow:inset 3px 0 #5b6e5c}.nav-empty{padding:15px 8px}.shop-panel{display:flex;flex-direction:column;min-height:0;overflow:hidden;border:1px solid #e4dac9;border-radius:9px;background:#fffcf6}.role-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:20px 20px 12px;flex:none}.role-heading>div{display:flex;align-items:baseline;gap:10px;min-width:0}.role-heading h2{font-size:19px;margin:0}.role-heading span,.role-heading small{font-size:11px;color:#998a74}.shop-list-tools{display:flex;gap:10px;align-items:center;padding:0 20px 14px;flex:none;flex-wrap:wrap}.shop-list-tools input{flex:1;min-width:120px}.shop-summary{display:flex;align-items:baseline;gap:16px;padding:0 20px 16px;font-size:11px;color:#998a74;flex:none}.shop-summary b{font-size:18px;color:#456052;font-weight:600}.shop-columns,.shop-item-row{display:grid;grid-template-columns:minmax(160px,1.1fr) minmax(170px,1.2fr) minmax(130px,.8fr);gap:16px;padding-inline:20px}.shop-columns{padding-block:11px;background:#f1ecdf;border-block:1px solid #e8dfd0;color:#97856d;font-size:11px;flex:none}.shop-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain}.shop-group-heading{padding:15px 20px 8px;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.shop-group-heading h3{font-size:11px;font-weight:500;color:#9c886c;margin:0;display:flex;gap:9px;align-items:center}.shop-group-heading h3 small{font-size:10px;color:#b4a58f}.wallets{display:flex;gap:12px;flex-wrap:wrap}.wallets>span{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:#998a74}.wallets b{color:#64765e;font-size:12px;font-weight:500}.wallets img,.item-price img{width:17px;height:17px;object-fit:contain}.shop-item-row{min-height:53px;align-items:center;border-bottom:1px solid #eee7da;padding-block:10px}.shop-item-row:hover{background:#f8f5ec}.shop-group:last-child .shop-item-row:last-child{border-bottom:0}.item-name{display:flex;align-items:center;gap:10px;min-width:0}.item-name>img{width:24px;height:24px;object-fit:contain;flex:none}.item-name strong{font-size:13px;font-weight:500;line-height:1.6}.item-name small{display:block;font-size:10px;line-height:1.7;color:#a18f76}.purchase-progress{font-size:12px;line-height:1.8;color:#7d7566;overflow-wrap:anywhere}.item-price{display:flex;gap:6px 10px;flex-wrap:wrap;font-size:11px;color:#897c69}.item-price>span{display:inline-flex;align-items:center;gap:5px}.empty{padding:45px 20px;text-align:center;color:#9e907a;font-size:13px}footer{font-size:11px;color:#a08e75;line-height:1.8;padding-top:12px;flex:none}.chooser{padding:20px;border-bottom:1px solid #e4dac9;background:#f8f4ea}.chooser-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.chooser-head h2{font-size:16px;margin:0 0 5px}.choices{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:8px;margin-top:18px}.choices label{display:flex;gap:9px;align-items:center;padding:9px;background:#fffcf6;border:1px solid #e8dfcf;border-radius:5px}.choices strong{font-size:12px;font-weight:500}.choices small{display:block;font-size:10px;color:#998a74;margin-top:3px}input[type=checkbox]{accent-color:#456052}
@media(max-width:1150px){.shop-layout{grid-template-columns:160px minmax(0,1fr);gap:15px}.shop-columns,.shop-item-row{grid-template-columns:minmax(135px,1fr) minmax(135px,1fr) minmax(105px,.8fr);gap:10px;padding-inline:15px}.role-heading{padding-inline:15px}.shop-list-tools,.shop-summary{padding-inline:15px}.shop-group-heading{padding-inline:15px}}
@media(max-width:850px){.shop-layout{grid-template-columns:135px minmax(0,1fr);gap:10px}.shop-columns{display:none}.shop-item-row{grid-template-columns:minmax(0,1fr) minmax(100px,.65fr);gap:5px 10px}.item-name{grid-column:1;grid-row:1}.purchase-progress{grid-column:1;grid-row:2;padding-left:34px;font-size:11px}.item-price{grid-column:2;grid-row:1/3}.role-heading small{font-size:10px}.shop-list-tools{gap:6px}.shop-list-tools select{max-width:125px}}
.shop-summary{border-bottom:1px solid #e8dfd0;padding-bottom:12px;flex-wrap:wrap}.fold-tools{margin-left:auto;display:flex;gap:5px}.fold-tools button{font-size:11px;background:transparent;border:0;padding:3px 5px;color:#998a74}.shop-group{padding:0 20px 18px}.shop-group-heading{padding:14px 0 10px}.shop-group-heading h3{flex:1;min-width:110px}.shop-fold{display:flex;align-items:center;gap:9px;width:100%;text-align:left;border:0;background:transparent;padding:4px 0;font-size:12px;color:#897c69}.shop-fold small{font-size:10px}.shop-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:10px}.shop-item-card{padding:13px 14px;background:#f7f3ea;border:1px solid #e8dfd0;border-radius:8px;min-width:0;display:flex;flex-direction:column;gap:13px}.shop-item-card.sold{background:#f1eee6}.card-name{display:flex;align-items:center;gap:10px;min-height:36px}.card-name img{width:34px;height:34px;object-fit:contain;flex:none}.card-name strong{font-size:13px;font-weight:500;line-height:1.6}.card-name small{display:block;font-size:10px;color:#a18f76;margin-top:3px}.card-purchase{display:flex;align-items:baseline;justify-content:space-between;gap:8px;flex-wrap:wrap;font-size:11px;color:#998a74}.card-purchase b{font-size:22px;color:#526750;font-weight:600}.card-purchase small{font-size:10px}.card-requirements{font-size:10px;line-height:1.7;color:#998a74}.card-price{margin-top:auto;padding-top:9px;border-top:1px solid #e4dac9;display:flex;align-items:center;gap:5px 8px;flex-wrap:wrap;font-size:11px;color:#897c69}.card-price>span{display:inline-flex;align-items:center;gap:5px}.card-price img{width:18px;height:18px;object-fit:contain}.card-price small{font-size:10px;margin-left:auto}@media(max-width:1150px){.shop-group{padding-inline:15px}.shop-cards{grid-template-columns:repeat(auto-fill,minmax(190px,1fr))}}@media(max-width:850px){.shop-cards{grid-template-columns:repeat(auto-fill,minmax(175px,1fr))}.wallets{gap:8px}.shop-group-heading{gap:5px}}
</style>
